// RESPONSIBILITY: Defines runtime validation schemas for coupons_management; it does not determine server-owned business rules without a verified contract.
// DATA FLOW: API/form boundary → Zod schema → validated typed data or field-level errors → owning hook/view (admin_coupons/coupons_management/schemas/AdminBillingCouponsManagementSchemas.ts)

import { z } from 'zod';
import { isAdminCouponUsageLimit } from '@/app/frontend_admin/admin_billing/billing_coupons_management/utils/AdminBillingCouponsManagementUsageLimit';
import { format, isValid, parseISO } from 'date-fns';
// Generated by ts-to-zod


export const statusSchema = z.union([z.literal("idle"), z.literal("loading"), z.literal("success"), z.literal("error")]);

export const couponTypeSchema = z.union([z.literal("percentage"), z.literal("flat")]);

export const couponStatusSchema = z.union([z.literal("active"), z.literal("inactive"), z.literal("expired")]);

/** Date-only values must be compared in local calendar space, never via UTC midnight. */
export const couponCalendarDateSchema = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine((value) => {
  const parsed = parseISO(value);
  return isValid(parsed) && format(parsed, 'yyyy-MM-dd') === value;
}, 'Invalid calendar date');

/** Currency-input precision is decimal text, not an IEEE-754 multiplication property. */
const atMostTwoDecimalPlaces = (value: string) => /^\d+(?:\.\d{1,2})?$/.test(value.trim());


export const couponSchema = z.object({
    id: z.string(),
    code: z.string(),
    description: z.string(),
    type: couponTypeSchema,
    value: z.number().finite().nonnegative(),
    minOrderAmount: z.number().int().nonnegative(),
    maxDiscount: z.number().int().nonnegative(),
    usageLimit: z.number().int().positive(),
    usedCount: z.number().int().nonnegative(),
    assignedGyms: z.array(z.string()),
    assignedGymNames: z.array(z.string()),
    validFrom: couponCalendarDateSchema,
    validUntil: couponCalendarDateSchema,
    status: couponStatusSchema,
    createdAt: z.string()
});

export const couponFormValuesSchema = z.object({
    code: z.string(),
    description: z.string(),
    type: couponTypeSchema,
    value: z.string(),
    minOrderAmount: z.string(),
    maxDiscount: z.string(),
    usageLimit: z.string(),
    assignedGyms: z.array(z.string()),
    validFrom: z.string(),
    validUntil: z.string()
});

export const couponsKpiDataSchema = z.object({
    totalCoupons: z.number().int().nonnegative(),
    activeCoupons: z.number().int().nonnegative(),
    totalRedeemed: z.number().int().nonnegative(),
    revenueLost: z.number().int().nonnegative()
});

export const couponFormSchema = z.object({
  code: z.string().trim().min(3, '__i18n:coupons.validation.codeMin').max(20, '__i18n:coupons.validation.codeMax').toUpperCase(),
  description: z.string().trim().min(5, '__i18n:coupons.validation.descriptionRequired'),
  type: z.enum(['percentage', 'flat']),
  value: z.string().refine(v => v.trim() !== '' && Number.isFinite(Number(v)) && Number(v) > 0, '__i18n:coupons.validation.positiveNumber').refine(v => atMostTwoDecimalPlaces(v), '__i18n:coupons.validation.maxTwoDecimals'),
  minOrderAmount: z.string().refine(v => v.trim() !== '' && Number.isFinite(Number(v)) && Number(v) >= 0, '__i18n:coupons.validation.nonNegativeNumber').refine(v => atMostTwoDecimalPlaces(v), '__i18n:coupons.validation.maxTwoDecimals'),
  maxDiscount: z.string().refine(v => v.trim() !== '' && Number.isFinite(Number(v)) && Number(v) >= 0, '__i18n:coupons.validation.nonNegativeNumber').refine(v => atMostTwoDecimalPlaces(v), '__i18n:coupons.validation.maxTwoDecimals'),
  usageLimit: z.string().refine(isAdminCouponUsageLimit, '__i18n:coupons.validation.usageMin'),
  assignedGyms: z.array(z.string().trim().min(1)).min(1, '__i18n:coupons.validation.gymsRequired'),
  validFrom: couponCalendarDateSchema,
  validUntil: couponCalendarDateSchema,
}).superRefine((value, context) => {
  if (value.validFrom > value.validUntil) context.addIssue({ code: z.ZodIssueCode.custom, path: ['validUntil'], message: '__i18n:coupons.validation.endBeforeStart' });
  if (value.assignedGyms.includes('all') && value.assignedGyms.length > 1) context.addIssue({ code: z.ZodIssueCode.custom, path: ['assignedGyms'], message: '__i18n:coupons.validation.allGymsExclusive' });
});



export const couponUpdatePayloadSchema = z.object({
  code: z.string().trim().min(3).max(20).optional(),
  description: z.string().trim().min(5).optional(),
  type: couponTypeSchema.optional(),
  value: z.number().finite().nonnegative().optional(),
  minOrderAmount: z.number().int().nonnegative().optional(),
  maxDiscount: z.number().int().nonnegative().optional(),
  usageLimit: z.number().int().positive().optional(),
  assignedGyms: z.array(z.string().min(1)).min(1).optional(),
  validFrom: couponCalendarDateSchema.optional(),
  validUntil: couponCalendarDateSchema.optional(),
}).strict().refine((value) => Object.keys(value).length > 0, 'At least one coupon field is required');
